/*
 * Stub implementations for Essentia algorithm registration functions.
 * 
 * In a full Essentia build, these functions are auto-generated by the build system
 * to register all algorithms. For our minimal CMake build, we provide empty stubs.
 * 
 * Algorithms are registered via static initialization when their translation units
 * are linked. This file just provides the function symbols that essentia::init() calls.
 */

#include "essentia.h"

namespace essentia {
namespace standard {

void registerAlgorithm() {
    // Empty stub - algorithms register themselves via static initializers
    // when their source files are compiled and linked
}

} // namespace standard

namespace streaming {

void registerAlgorithm() {
    // Empty stub - streaming algorithms register themselves via static initializers
}

} // namespace streaming
} // namespace essentia
